## The Calculator That Won't Crash

Parsing a math expression means extracting the operator and operands from a string.

### Simple Two-Number Expression

```xiom
fn calculate(expr: Str) -> Result[Int, Str] {
  // Find the operator
  let plus_pos = -1;
  let i = 0;
  while i < string.str_length(expr) {
    if string.str_slice(expr, i, i + 1) == "+" { plus_pos = i; }
    i = i + 1;
  }

  if plus_pos == -1 {
    return Err("No operator found in expression");
  }

  let left_str = string.str_slice(expr, 0, plus_pos);
  let right_str = string.str_slice(expr, plus_pos + 1, string.str_length(expr));

  let left = string.str_to_int(left_str)?;
  let right = string.str_to_int(right_str)?;

  return Ok(left + right);
}

fn main() -> Int {
  match calculate("5+3") {
    Ok(result) => io.println("5+3 = " + string.int_to_str(result)),  // 8
    Err(e) => io.println("Error: " + e),
  };
  match calculate("42+58") {
    Ok(result) => io.println("42+58 = " + string.int_to_str(result)),  // 100
    Err(e) => io.println("Error: " + e),
  };
  match calculate("hello") {
    Ok(result) => io.println(string.int_to_str(result)),
    Err(e) => io.println("Error: " + e),  // No operator found
  };
  match calculate("5+abc") {
    Ok(result) => io.println(string.int_to_str(result)),
    Err(e) => io.println("Error: " + e),  // Parse error
  };
  return 0;
}
```

### Handling Subtraction Too

```xiom
fn find_operator(expr: Str, op: Str) -> Int {
  let i = 0;
  while i < string.str_length(expr) {
    if string.str_slice(expr, i, i + 1) == op { return i; }
    i = i + 1;
  }
  return -1;
}

fn calculate_v2(expr: Str) -> Result[Int, Str] {
  let op_pos = find_operator(expr, "+");
  let is_add = true;
  if op_pos == -1 {
    op_pos = find_operator(expr, "-");
    is_add = false;
  }
  if op_pos == -1 {
    return Err("No operator found");
  }

  let left = string.str_to_int(string.str_slice(expr, 0, op_pos))?;
  let right = string.str_to_int(string.str_slice(expr, op_pos + 1, string.str_length(expr)))?;

  if is_add { return Ok(left + right); }
  return Ok(left - right);
}
```

