use xiom.io;

use xiom.string;
fn calculate(expr: Str) -> Result[Int, Str] {
  let pos = -1;
  let i = 0;
  while i < str_len(expr) {
    if string.str_slice(expr, i, i + 1) == "+" { pos = i; }
    i = i + 1;
  }
  if pos == -1 { return Err("No + operator found"); }

  let left_str = string.str_slice(expr, 0, pos);
  let right_str = string.str_slice(expr, pos + 1, str_len(expr));

  let left = string.str_to_int(left_str)?;
  let right = string.str_to_int(right_str)?;

  return Ok(left + right);
}

fn main() -> Int {
  io.println(calculate("10+20").unwrap_or(-1).to_str());
  io.println(calculate("-5+3").unwrap_or(-1).to_str());
  io.println(calculate("abc").unwrap_or(-1).to_str());
  io.println(calculate("1+2+3").unwrap_or(-1).to_str());
  return 0;
}
